     5	
     6	export interface LiveTranscriptState {
     7		turns: LiveTranscriptTurn[];
     8		draft: LiveTranscriptTurn;
     9	}
    10	
    11	export type LiveTranscriptRole = keyof LiveTranscriptTurn;
    12	
    13	export function emptyLiveTranscript(): LiveTranscriptState {
    14		return {
    15			turns: [],
    16			draft: { user: "", assistant: "" },
    17		};
    18	}
    19	
    20	function mergeTranscript(current: string, text: string, final: boolean): string {
    21		if (final) return text || current;
    22		return current + text;
    23	}
    24	
    25	function completedDraft(state: LiveTranscriptState): LiveTranscriptState {
    26		const user = state.draft.user.trim();
    27		const assistant = state.draft.assistant.trim();
    28		if (!user && !assistant) return state;
    29		return {
    30			turns: [...state.turns, { user, assistant }],
    31			draft: { user: "", assistant: "" },
    32		};
    33	}
    34	
    35	/**
    36	 * Fold provider transcript callbacks into conversational turns.
    37	 *
    38	 * OpenAI completes a turn with the full assistant transcript while Gemini
    39	 * completes it with an empty final marker. In both cases, an assistant final
    40	 * closes the user/assistant pair. User finals only settle their side of the
    41	 * draft because the answer is still on its way.
    42	 */
    43	export function appendLiveTranscript(
    44		state: LiveTranscriptState,
    45		role: LiveTranscriptRole,
    46		text: string,
    47		final: boolean,
    48	): LiveTranscriptState {
    49		const next = {
    50			...state,
    51			draft: {
    52				...state.draft,
    53				[role]: mergeTranscript(state.draft[role], text, final),
    54			},
    55		};
    56		return role === "assistant" && final ? completedDraft(next) : next;
    57	}
    58	
    59	/** Preserve a partially transcribed turn when the learner ends the session. */
    60	export function flushLiveTranscript(state: LiveTranscriptState): LiveTranscriptState {
    61		return completedDraft(state);
    62	}

